pragma solidity ^0.8.20;

/**
 * @title NGODonation
 * @author Your Name
 * @notice A smart contract for managing donation campaigns for NGOs.
 * @dev This contract allows an owner to create and manage campaigns, donors to contribute ETH,
 * and beneficiaries to withdraw funds. It includes inline implementations of Ownable, Pausable,
 * and ReentrancyGuard patterns to avoid external dependencies.
 */
contract NGODonation {
    // =============================================================
    // Custom Errors (for gas efficiency)
    // =============================================================
    error NotOwner();
    error ZeroAddress();
    error Paused();
    error NotPaused();
    error ReentrantCall();
    error CampaignDoesNotExist();
    error CampaignNotActive();
    error CampaignAlreadyClosed();
    error NotAuthorized();
    error DonationMustBeGreaterThanZero();
    error WithdrawAmountMustBeGreaterThanZero();
    error InsufficientCampaignBalance();
    error TransferFailed();
    error DirectETHTransfersNotAllowed();

    // =============================================================
    // State for Inline Patterns
    // =============================================================

    // --- Ownable State ---
    address private _owner;

    // --- Pausable State ---
    bool private _paused;

    // --- ReentrancyGuard State ---
    uint256 private _reentrancyStatus;
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;

    // =============================================================
    // Contract-Specific State
    // =============================================================

    enum Status { Active, Closed }

    struct Campaign {
        uint256 id;
        string name;
        string metadataURI;
        address payable beneficiary;
        uint256 goal;
        uint256 amountRaised;
        uint256 amountWithdrawn;
        Status status;
    }

    Campaign[] private _campaigns;
    uint256 private _campaignIdCounter;

    mapping(uint256 => mapping(address => uint256)) public donorTotal;

    // =============================================================
    // Events
    // =============================================================

    // --- Pattern Events ---
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event PausedState(bool isPaused);

    // --- Application Events ---
    event CampaignCreated(uint256 indexed campaignId, address indexed beneficiary, uint256 goal, string name);
    event DonationReceived(uint256 indexed campaignId, address indexed donor, uint256 amount, string message);
    event FundsWithdrawn(uint256 indexed campaignId, address indexed beneficiary, uint256 amount);
    event CampaignClosed(uint256 indexed campaignId);

    // =============================================================
    // Modifiers
    // =============================================================

    modifier onlyOwner() {
        if (msg.sender != _owner) revert NotOwner();
        _;
    }

    modifier whenNotPaused() {
        if (_paused) revert Paused();
        _;
    }

    modifier whenPaused() {
        if (!_paused) revert NotPaused();
        _;
    }

    modifier nonReentrant() {
        if (_reentrancyStatus == _ENTERED) revert ReentrantCall();
        _reentrancyStatus = _ENTERED;
        _;
        _reentrancyStatus = _NOT_ENTERED;
    }

    // =============================================================
    // Constructor
    // =============================================================

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
        _reentrancyStatus = _NOT_ENTERED;
    }

    // =============================================================
    // External Functions
    // =============================================================

    /**
     * @notice Creates a new donation campaign.
     * @dev Only the contract owner can call this function.
     * @param name The name of the campaign.
     * @param metadataURI A URI pointing to campaign metadata (e.g., IPFS).
     * @param beneficiary The address that can withdraw the funds.
     * @param goal The funding goal in wei.
     * @return campaignId The ID of the newly created campaign.
     */
    function createCampaign(
        string calldata name,
        string calldata metadataURI,
        address payable beneficiary,
        uint256 goal
    ) external onlyOwner returns (uint256) {
        if (beneficiary == address(0)) revert ZeroAddress();

        _campaignIdCounter++;
        uint256 campaignId = _campaignIdCounter;

        _campaigns.push(Campaign({
            id: campaignId,
            name: name,
            metadataURI: metadataURI,
            beneficiary: beneficiary,
            goal: goal,
            amountRaised: 0,
            amountWithdrawn: 0,
            status: Status.Active
        }));

        emit CampaignCreated(campaignId, beneficiary, goal, name);
        return campaignId;
    }

    /**
     * @notice Donates ETH to a specific campaign.
     * @dev Can be called by anyone. Contract must not be paused.
     * @param campaignId The ID of the campaign to donate to.
     * @param message A message from the donor.
     */
    function donate(uint256 campaignId, string calldata message) external payable whenNotPaused nonReentrant {
        if (msg.value == 0) revert DonationMustBeGreaterThanZero();
        if (campaignId == 0 || campaignId > _campaignIdCounter) revert CampaignDoesNotExist();

        Campaign storage campaign = _campaigns[campaignId - 1];
        if (campaign.status != Status.Active) revert CampaignNotActive();

        campaign.amountRaised += msg.value;
        donorTotal[campaignId][msg.sender] += msg.value;

        emit DonationReceived(campaignId, msg.sender, msg.value, message);
    }

    /**
     * @notice Allows a campaign's beneficiary to withdraw collected funds.
     * @param campaignId The ID of the campaign to withdraw from.
     * @param amount The amount of ETH (in wei) to withdraw.
     */
    function withdraw(uint256 campaignId, uint256 amount) external nonReentrant {
        if (campaignId == 0 || campaignId > _campaignIdCounter) revert CampaignDoesNotExist();

        Campaign storage campaign = _campaigns[campaignId - 1];
        if (msg.sender != campaign.beneficiary) revert NotAuthorized();
        if (amount == 0) revert WithdrawAmountMustBeGreaterThanZero();

        uint256 availableBalance = campaign.amountRaised - campaign.amountWithdrawn;
        if (amount > availableBalance) revert InsufficientCampaignBalance();

        // Checks-Effects-Interactions Pattern
        campaign.amountWithdrawn += amount;

        (bool success, ) = campaign.beneficiary.call{value: amount}("");
        if (!success) revert TransferFailed();

        emit FundsWithdrawn(campaignId, campaign.beneficiary, amount);
    }

    /**
     * @notice Closes a campaign, preventing further donations.
     * @dev Can be called by the contract owner or the campaign beneficiary.
     * @param campaignId The ID of the campaign to close.
     */
    function closeCampaign(uint256 campaignId) external {
        if (campaignId == 0 || campaignId > _campaignIdCounter) revert CampaignDoesNotExist();

        Campaign storage campaign = _campaigns[campaignId - 1];
        if (msg.sender != _owner && msg.sender != campaign.beneficiary) revert NotAuthorized();
        if (campaign.status == Status.Closed) revert CampaignAlreadyClosed();

        campaign.status = Status.Closed;
        emit CampaignClosed(campaignId);
    }

    // =============================================================
    // Owner-Only Administrative Functions
    // =============================================================

    /**
     * @notice Pauses the donation functionality of the contract.
     * @dev Only the contract owner can call this.
     */
    function pause() external onlyOwner whenNotPaused {
        _paused = true;
        emit PausedState(true);
    }

    /**
     * @notice Unpauses the donation functionality of the contract.
     * @dev Only the contract owner can call this.
     */
    function unpause() external onlyOwner whenPaused {
        _paused = false;
        emit PausedState(false);
    }

    /**
     * @notice Transfers ownership of the contract to a new account.
     * @dev Can only be called by the current owner.
     * @param newOwner The address of the new owner.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }

    // =============================================================
    // View Functions
    // =============================================================

    /**
     * @notice Retrieves details for a specific campaign.
     * @param campaignId The ID of the campaign.
     * @return id The unique ID of the campaign.
     * @return name The name of the campaign.
     * @return metadataURI A URI pointing to campaign metadata.
     * @return beneficiary The address that can withdraw the funds.
     * @return goal The funding goal in wei.
     * @return amountRaised The total amount raised for the campaign in wei.
     * @return amountWithdrawn The total amount withdrawn from the campaign in wei.
     * @return status The current status of the campaign (Active or Closed).
     */
    function getCampaign(uint256 campaignId)
        external
        view
        returns (
            uint256 id,
            string memory name,
            string memory metadataURI,
            address payable beneficiary,
            uint256 goal,
            uint256 amountRaised,
            uint256 amountWithdrawn,
            Status status
        )
    {
        if (campaignId == 0 || campaignId > _campaignIdCounter) revert CampaignDoesNotExist();
        Campaign storage c = _campaigns[campaignId - 1];
        return (
            c.id,
            c.name,
            c.metadataURI,
            c.beneficiary,
            c.goal,
            c.amountRaised,
            c.amountWithdrawn,
            c.status
        );
    }

    /**
     * @notice Gets the total number of campaigns created.
     * @return The campaign count.
     */
    function campaignCount() external view returns (uint256) {
        return _campaignIdCounter;
    }

    /**
     * @notice Gets the total amount raised for a specific campaign.
     * @param campaignId The ID of the campaign.
     * @return The total amount raised in wei.
     */
    function campaignRaised(uint256 campaignId) external view returns (uint256) {
        if (campaignId == 0 || campaignId > _campaignIdCounter) revert CampaignDoesNotExist();
        return _campaigns[campaignId - 1].amountRaised;
    }

    /**
     * @notice Returns the address of the current owner.
     */
    function owner() external view returns (address) {
        return _owner;
    }

    /**
     * @notice Returns true if the contract is paused, and false otherwise.
     */
    function paused() external view returns (bool) {
        return _paused;
    }

    // =============================================================
    // ETH Reception
    // =============================================================

    /**
     * @dev Rejects direct ETH transfers to prevent accidental locking of funds.
     */
    receive() external payable {
        revert DirectETHTransfersNotAllowed();
    }
}

